def fold(cells):
    for (r,c) in cells:
        if all((r+dr,c+dc) in cells for dr in (0,1) for dc in (0,1)): return None
    def roll(o,d):
        B,T,N,S,E,W=o
        return {'E':(E,W,N,S,T,B),'W':(W,E,N,S,B,T),'S':(S,N,B,T,E,W),'N':(N,S,T,B,E,W)}[d]
    start=sorted(cells)[0]
    faces={}; seen={start}; stack=[(start,('B','T','N','S','E','W'))]
    while stack:
        cell,o=stack.pop()
        if o[0] in faces: return None
        faces[o[0]]=cells[cell]
        for d,(dr,dc) in (('E',(0,1)),('W',(0,-1)),('S',(1,0)),('N',(-1,0))):
            nx=(cell[0]+dr,cell[1]+dc)
            if nx in cells and nx not in seen:
                seen.add(nx); stack.append((nx,roll(o,d)))
    return faces if len(faces)==6 else None
OPP={'B':'T','T':'B','N':'S','S':'N','E':'W','W':'E'}
def opposite(cells,label):
    f=fold(cells); inv={v:k for k,v in f.items()}
    return f[OPP[inv[label]]]
result=opposite({(0,0):1,(0,1):2,(1,1):3,(1,2):4,(1,3):5,(2,3):6},2)

def sd(dims,A,B,FA,FB):
    best=10**9
    for fa in FA:
        for fb in FB:
            if fa[0]==fb[0]: continue
            free=({0,1,2}-{fa[0],fb[0]}).pop()
            def f(t):
                p=[0,0,0]; p[fa[0]]=fa[1]; p[fb[0]]=fb[1]; p[free]=t
                return sqrt(sum((p[i]-A[i])**2 for i in range(3)))+sqrt(sum((p[i]-B[i])**2 for i in range(3)))
            lo,hi=0.0,float(dims[free])
            for _ in range(200):
                m1=lo+(hi-lo)/3; m2=hi-(hi-lo)/3
                if f(m1)<f(m2): hi=m2
                else: lo=m1
            best=min(best,f((lo+hi)/2))
    return best
